local OverseaMallInventoryPopup = Class("OverseaMallInventoryPopup")
local Cell = "Cell"
local InventoryCellPath = "Game.OverseaStore.Cell.OverseaMallInventoryPopUpCell"
local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local SDKService = import('Game.Entry.SDKService')
local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()

function OverseaMallInventoryPopup:__init()
end

function OverseaMallInventoryPopup:Awake()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    self:AddUIClick()
    self:InitEnv()
end

function OverseaMallInventoryPopup:InitEnv()
    if self.OriginalPrice then
        local env = CfUtils.GetLuaScr(self.OriginalPrice,CurryEnvPath)
        if env then
            self.originalPriceEnv = env
        end
    end

    if self.NowPrice then
        local env = CfUtils.GetLuaScr(self.NowPrice,CurryEnvPath)
        if env then
            self.nowPriceEnv = env
        end
    end
end

function OverseaMallInventoryPopup:AddUIClick()
    SetButtonAction(self.BtnClose.gameObject,Bind(self,self.OnBtnCloseClick))
    SetButtonAction(self.BtnDirectPurchase,Bind(self,self.OnBtnDirectPurchaseClick))
    SetButtonAction(self.BtnCurrencyPurchase,Bind(self,self.OnBtnCurrencyPurchaseClick))
end

--支付成功
function OverseaMallInventoryPopup:OnEventSdkEvent(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        ---把自己关了
        self:OnBtnCloseClick()
        Events.Broadcast(Constants.EventNames.OverseaMallRenovateBuySuccess)
    end
end

function OverseaMallInventoryPopup:OnBtnDirectPurchaseClick()
    if checkNumber(self.data.stock) <= 0 then
        GameUtils.Toast(localize("库存不足"))
        return
    end

    local suitVo = MaidCoffeeUtils.GetSuitRenovateVo(self.data.avatarSuitId)
    SDKService:GetInstance():PayMoney({
        productId = self.data.productId,
        channelProductId = self.data.channelProductId,
        productDesc = suitVo.name,
        payAmount = checkNumber(self.data.price),
        data = self.data
    })
end

function OverseaMallInventoryPopup:OnBtnCurrencyPurchaseClick()
    if checkNumber(self.data.stock) <= 0 then
        GameUtils.Toast(localize("库存不足"))
        return
    end
    local buyFunc = function()
        GameUtils.Request(Interfaces.OverseaMallRenovateShopBuy,{productId = self.data.productId, num = 1 ,currency = self.data.prices[1].currency},function(request,response)
            if checkNumber(response.errCode) == 0 then
                local data = response.data
                GoodsUtils.DrawRewards({ { goodsId = self.data.prices[1].currency, num = -self.data.prices[1].current , productId = checkNumber(self.data.productId)} }, true)
                ---把自己关了
                self:OnBtnCloseClick()
                if #data.rewards > 0 then
                    GoodsUtils.DrawRewards(data.rewards)
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = data.rewards, cb = function()
                                    Events.Broadcast(Constants.EventNames.OverseaMallRenovateBuySuccess)
                                end }
                            }
                    )
                else
                    Events.Broadcast(Constants.EventNames.OverseaMallRenovateBuySuccess)
                end
            end
        end)
    end
    
    local currency = self.data.prices[1].currency
    local current = self.data.prices[1].current
    if currency == Constants.Currency.PayDiamondId or currency == Constants.Currency.FreeDiamondId then
        ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
            currency = currency,
            current = current,
        },Bind(self,function()
            buyFunc()
        end),Bind(self,self.RefreshPriceShow))
    else
        local haveNum = GoodsUtils.GetThingNo(currency)
        if haveNum >= current then
            buyFunc()
        else
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(currency)
            if goodsVo then
                GameUtils.Toast(localize("_name_不足",{_name_ = goodsVo.name}))
            end
        end
    end
end

function OverseaMallInventoryPopup:StartCountDown()
    local remainTime = self.data.remainTime
    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(remainTime)))
    self:RemoveTimer()
    if remainTime > 0 then
        self.isTimeOver = false
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(count)))
            else
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(0)))
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.isTimeOver = true
                self.Timer = nil
            end
        end, remainTime + 1, false, true)
    end
end

function OverseaMallInventoryPopup:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end


function OverseaMallInventoryPopup:OnFocus(focus)
    if focus then
        if self.data then
            CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId, self.data.prices[1].currency})
        end
    end
end

function OverseaMallInventoryPopup:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:RefreshShow()
        end)
    end))
    return coWait
end


function OverseaMallInventoryPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            self:InitData(self.parameters.data)
        end)
    end))
    return coWait
end

function OverseaMallInventoryPopup:InitData(data)
    self.data = data
end

function OverseaMallInventoryPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:RemoveTimer()
            self:Delete()
            self = nil --lua层的gc需要
        end)
    end))
    return coWait
end

function OverseaMallInventoryPopup:__delete()
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    self.data = nil
    self.controller = nil
end

function OverseaMallInventoryPopup:RefreshShow()
    local suitVo = MaidCoffeeUtils.GetSuitRenovateVo(self.data.avatarSuitId)
    CfUtils.FillText(self.TextDesc,localize("_name_包含以下部件：",{_name_ = suitVo.name}))
    
    self:RefreshGridShow()
    self:RefreshPriceShow()
    self:StartCountDown()
end

function OverseaMallInventoryPopup:RefreshPriceShow()
    local isDirect = (not next(self.data.prices))
    KTool.SetActive(self.BtnCurrencyPurchase.gameObject,not isDirect)
    KTool.SetActive(self.BtnDirectPurchase.gameObject,isDirect)
    if isDirect then
        CfUtils.FillText(self.DirectOriginalPrice, CfUtils.GetCustomDisplayPrice(self.data.original, nil, 24))
        local windowsPriceId =  CfUtils.GetWindowsPriceId(self.data)
        CfUtils.FillText(self.DirectNowPrice, CfUtils.GetCustomDisplayPrice(windowsPriceId, self.data.channelProductId, 24))
    else
        local goodId = self.data.prices[1].currency
        self.originalPriceEnv:SetCurrencyShow(goodId ,self.data.prices[1].original)
        self.nowPriceEnv:SetCurrencyShow(goodId ,self.data.prices[1].current)
    end
end

function OverseaMallInventoryPopup:RefreshGridShow()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#self.data.rewards, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self.data.rewards)
    end
end

function OverseaMallInventoryPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.data.rewards < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,InventoryCellPath)
        if env then
            local data = self.data.rewards[index + 1]
            env:RefreshShow(data,self.curIndex,index + 1)
        end
    end
    return cell
end

function OverseaMallInventoryPopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end


return OverseaMallInventoryPopup